record.field:
action = env["ir.actions.actions"]._for_xml_id("x_budget.account_analytic_line_action")
action["context"] = {
    "active_id": record.id,
    "active_model": record._name,
    "default_account_id": record.x_analytic_account_id.id,
    "default_date": record.x_start_date.strftime('%Y-%m-%d') if record.x_start_date else False,
}
action["domain"] = [
    ("account_id", "=", record.x_analytic_account_id.id),
    ("x_budget_category_id", "not in", record.x_category_ids.ids),
]
if record.x_use_dates and record.x_start_date and record.x_stop_date:
    action["domain"] += [("date", ">=", record.x_start_date.strftime('%Y-%m-%d')), ("date", "<=", record.x_stop_date.strftime('%Y-%m-%d'))]
